import type{HotelChapterContent}from'./hospitalityHotelsContentTypes';
export const HOTEL_CONTENT_M1:Record<string,HotelChapterContent>={
"m1-1":{i:"Hotels and resorts sell time-limited lodging capacity together with the services around it, so selling more rooms does not by itself make a property profitable.",w:"The industry provides paid overnight accommodation to travelers and usually adds dining, meeting space, recreation and other services under one operation. STR counts a hotel as a property that is typically open to the public, generates nightly revenue and has ten or more rooms.",y:"Travel for leisure and business creates a steady need for somewhere to sleep away from home, and operators compete to turn that need into repeat stays. Because the building and staff exist whether or not rooms sell, owners try to fill capacity with higher-value services as well as rooms.",e:"STR's glossary separates the room business from the rest of a hotel's income by reporting rooms revenue, food and beverage revenue, other departments such as spa, golf and parking, and miscellaneous income such as resort and cancellation fees.",v:"Decree 168/2017/ND-CP treats hotels as one category of tourist accommodation alongside tourist villas, apartments, cruise ships and other types, so a Vietnamese owner first decides which legal category the property belongs to.",b:"Defining the business broadly helps owners see revenue beyond rooms, but it also adds departments with their own costs and risks. A property is judged on the whole guest offer and on the cost of delivering it.",s:["str","vnDecree"],t:[["Lodging","An umbrella term for any temporary place for travelers to sleep, from hotels and motels to hostels, vacation rentals and bed and breakfasts.","str"],["Hotel property","In STR's definition, an accommodation business that typically has ten or more rooms, is open to the public and generates nightly revenue.","str"],["Rooms revenue","Revenue earned from renting guest rooms, reported net of any rebates and discounts.","str"],["Total revenue","All revenue from hotel operations, covering rooms, food and beverage, other departments such as spa and golf, and miscellaneous income.","str"],["Miscellaneous income","Revenue outside rooms, food and beverage and other operated departments, such as space rentals, resort fees and cancellation fees.","str"]]},
"m1-2":{i:"A hotel sells a perishable room night that cannot be stored while most of its costs are fixed, so its economics depend on timing, mix and execution as much as on demand.",w:"Hotel operations combine a fixed building, round-the-clock service and a product that expires each night, with guest-facing and back-of-house teams working together. Capacity is counted as rooms multiplied by days in the period, which shows that it is fixed for every date.",y:"Guests expect service at all hours and a stay that matches the promise made at booking, so hotels staff and maintain capacity before they know how many rooms will sell. Reservations, housekeeping and engineering must stay coordinated across every shift.",e:"STR's glossary shows supply as rooms multiplied by days, so 100 rooms over a 31-day month give 3,100 room nights available. A room left empty on any one of those nights cannot be sold again later.",v:"Under Article 22 of Decree 168/2017 as amended by Decree 142/2018, a hotel retains a reception requirement and employees on duty 24 hours a day, so continuous staffing remains part of the hotel-specific minimum.",b:"Fixed capacity and continuous service raise the cost of every empty room, so owners focus on filling nights at a sustainable rate while holding service quality. Unit economics can look strong on busy dates and weak on quiet ones.",s:["str","vnDecree","vnDecree142"],t:[["Rooms available","The number of rooms in a hotel multiplied by the number of days in a period, which sets the capacity that could have been sold.","str"],["Room night","One room for one night, the unit in which hotels count the supply they offer and the rooms they sell.","str"],["Perishable inventory","A product such as a room night that has value only for one date and cannot be stored or sold after that date passes."],["Front of house","The guest-facing parts of a hotel, such as reception, lobby, concierge and restaurants, where service is delivered in view of guests."],["Back of house","The staff and technical areas guests do not normally see, such as kitchens, laundry, engineering and housekeeping stores."]]},
"m1-3":{i:"The boundary of the hotel industry is set by what a property sells, to whom and under which legal category, and it blurs where lodging overlaps with apartments, homes and tours.",w:"The core of the industry is licensed, commercially operated lodging that sells rooms by the night, while related formats such as serviced apartments, villas, timeshare and alternative accommodation sit at its edges. STR lists hotel types including all-suite, extended stay, timeshare and condo.",y:"Travelers now choose from many formats for the same trip, so brands extend into apartments, residences and mixed use to keep guests inside their own ecosystem. Accor's brand page lists branded residential and mixed use, all-inclusive resorts and extended stay among its growth areas.",e:"Accor describes a portfolio that runs from luxury and lifestyle names such as Raffles and Sofitel to economy names such as ibis budget, and it also lists apartment-style brands such as Adagio, showing how one group's range spans several lodging formats.",v:"Decree 168/2017/ND-CP lists seven types of tourist accommodation, from urban hotels and resorts to tourist villas, apartments, cruise ships, rest houses, houses with rooms for rent and camping sites, each with its own minimum conditions.",b:"Where the line is drawn decides which competitors, regulations and benchmarks apply to a property. An owner who compares against the wrong boundary misreads both the opportunity and the compliance duty.",s:["str","accor","vnDecree"],t:[["Extended stay","A property type that focuses on guests staying for longer periods and typically quotes weekly rates.","str"],["Timeshare","A property, usually a resort condominium unit, in which several parties hold rights to use it and each is allotted a period of use.","str"],["All-inclusive","A property that sells rooms only as a package bundling accommodation with food, drink, activities and gratuities.","str"],["Tourist apartment","In Vietnam's decree, an apartment equipped with the facilities and services tourists need, which they may use on a self-serve basis during their stay.","vnDecree"],["Tourist villa","In Vietnam's decree, a villa equipped for rent to tourists, who may use its facilities themselves during their stay.","vnDecree"]]},
"m1-4":{i:"Hotel categories group properties by price level, service depth, location and format, and each category carries different guest expectations and operating costs.",w:"Categories describe how a property is positioned using service level, average rate, location type and facilities. STR separates full-service hotels, with a wide range of onsite amenities, from limited-service hotels that offer focused facilities and usually no full restaurant.",y:"Different guests want different trade-offs between price, space and service, so operators design distinct models rather than one standard hotel. Service depth drives staffing, so a broader offer needs more teams and a larger cost base.",e:"STR groups chain hotels into scales from luxury and upper upscale through midscale and economy, and it treats independent hotels as a separate category regardless of their average room rate.",v:"Decree 168/2017/ND-CP defines resorts as complexes of villas, low-rise buildings or apartments in areas with beautiful natural landscapes, and urban hotels as accommodation built in urban centers, so the legal categories already reflect location.",b:"Choosing a category fixes the price range a hotel can credibly charge and the service it must deliver to earn it. Mismatches between promise and delivery show up first in guest reviews and in rate.",s:["str","accor","vnDecree"],t:[["Full-service hotel","A hotel, typically upscale or luxury, with a wide range of onsite amenities such as restaurants, meeting spaces and spas.","str"],["Limited-service hotel","A hotel offering focused facilities and amenities, usually without a full-service restaurant, which needs a smaller operating staff.","str"],["Chain scale","A grouping of chain hotels mainly by average room rate, from luxury down to economy, with independent hotels shown separately.","str"],["Boutique hotel","A mostly independent property that appeals through atypical rooms and amenities, offers high service levels and often a local cultural experience.","str"],["Resort hotel","In Vietnam's decree, accommodation built as blocks or complexes of villas, low-rise buildings or apartments in an area of beautiful natural scenery.","vnDecree"]]},
"m1-5":{i:"A hotel serves guests, owners, operators, brands, distributors, staff and regulators at once, and their interests do not always point the same way.",w:"Customers include leisure travelers, business travelers, groups and long-stay guests, while stakeholders include the owner who funds the asset, the operator who runs it, the brand that licenses systems and the intermediaries that distribute rooms. STR's company types separate owners, operators, franchise companies and developers.",y:"Hotel ownership, operation and branding can sit with separate businesses, so decisions are shared and incentives can differ between the parties. Each stakeholder also answers to a different audience, from guests to lenders to authorities.",e:"Marriott describes itself as a franchisor, operator and licensor and says it owns or leases very few of its properties, which means most hotels in its system are owned by other parties who contract with Marriott for the brand or for management.",v:"Article 22 of Decree 168/2017 must be read together with Decree 142/2018: the amended hotel-specific minimum retains staff on duty 24 hours a day, while the original tourism-training clause was repealed. Training remains an operating capability and may be required by other law, ratings, brands or contracts.",b:"Each stakeholder measures success differently, from guest satisfaction to owner cash return to brand fee income. Clear contracts about who decides what and who bears which cost prevent disputes later.",s:["str","marriott","vnDecree","vnDecree142"],t:[["Owner","The person or company that primarily owns lodging properties rather than franchising or managing them; several owners may share one property.","str"],["Operator","A management company that runs a property's operations on behalf of its owners, typically in return for fees or a share of revenue.","str"],["Franchise company","A company that licenses a name and logo to independently owned hotels for an annual fee plus royalties, giving them shared brand identity, reservations and training.","str"],["Developer","A company that prepares a site and builds a lodging facility for commercial use.","str"],["Asset manager","A company or contact that handles a hotel's financial arrangements for the owner, such as loans, appraisals and management requirements.","str"]]},
"m1-6":{i:"Commercial lodging moved from independent, locally run houses toward organized hotels whose value rests on standards, systems and trusted names as well as buildings.",w:"Commercial accommodation grew from locally run lodging for travelers into organized hotels, and later into chains that standardize service across many places. STR still separates independent hotels, which are not affiliated with a chain, from branded ones.",y:"As travel spread, guests wanted predictable quality in unfamiliar places, and owners wanted help reaching travelers they could not market to alone. Both pressures rewarded shared standards, reservation systems and recognizable names.",e:"Four Seasons says it opened its first hotel in 1961 and presents its history as decades of expansion held together by a consistent thread of service, an example of one company's path from a first property to a global brand.",v:"The cited sources do not give a dated history of Vietnamese accommodation. The regulatory link is Decree 168/2017, effective 1 January 2018, read with the amendments in Decree 142/2018 when applying current minimum conditions.",b:"Understanding how lodging organized itself explains why today's owners must choose between independence and a brand. Each path trades control for reach and standards.",s:["str","fourSeasons","marriott","vnDecree","vnDecree142"],t:[["Independent hotel","A property not affiliated with a chain and independently operated, including non-branded hotels and some membership-based brands.","str"],["Affiliation","A publicly recognized brand or chain with consistent standards across a group of properties, which a hotel joins on a stated date.","str"],["Brand standards","Required service, design and operating specifications that a brand imposes so guests find consistent quality across its properties."],["Reservation system","A central booking platform, provided by a brand or chain, through which its member hotels take reservations.","marriott"],["Loyalty program","A membership scheme that rewards repeat stays with points and benefits, designed to bring guests back to a brand's hotels.","marriott"]]},
"m1-7":{i:"Modern chains grew by selling a brand, a booking network and a loyalty program to many property owners rather than by owning every hotel themselves.",w:"A chain is a group of properties operating under a recognized brand with consistent standards, usually backed by central reservations, marketing and loyalty. Parent companies can hold several brands, and STR lists Accor and Marriott International as examples.",y:"Owners gain demand and credibility from a known name, and brands gain fee income and scale without carrying property investment on their own balance sheet. That exchange encourages brands to add properties quickly through contracts.",e:"Marriott says approximately 68 percent of its global hotel room nights in 2025 were booked by loyalty program members, and it describes the program as generating substantial repeat business that might otherwise go to competing properties.",v:"In Vietnam, brand standards sit on top of the current statutory framework rather than replacing it. Apply Decree 168/2017 together with Decree 142/2018 and any other rules relevant to the property and service.",b:"Chain growth shifted competition from single buildings to platforms, so a hotel's results increasingly reflect the strength of its brand system as well as its location. Owners should price that benefit against the fees it brings.",s:["str","marriott","accor","vnDecree","vnDecree142"],t:[["Parent company","A company that owns one or more hotel brands, for example Accor or Marriott International.","str"],["Lifestyle brand","A group of hotels operating under one brand adapted to reflect current trends in design and guest experience.","str"],["Soft brand","A collection of properties that lets owners affiliate with a major chain while keeping their own name, design and orientation.","str"],["Brand portfolio","The set of brands a hotel group manages across price levels and styles, such as luxury, premium, midscale and economy.","accor"],["Converted in","Rooms added to a chain's inventory when an existing hotel switches over from another brand or from independence.","str"]]},
"m1-8":{i:"Management contracts and franchising let brands spread across many owners, while resorts grew by bundling lodging with destination experiences.",w:"Under a management contract the operator runs the hotel for the owner in return for fees, while under franchising the owner or its operator runs the hotel and pays for the brand and systems. Resorts add recreation, wellness and dining to create a complete destination stay.",y:"Owners who lack hotel operating skill want an experienced operator, while owners who can operate want only the brand, and each contract type answers one of those needs. Leisure travelers also pay more for a coherent destination experience than for rooms alone.",e:"STR classifies operation types as chain managed, franchised and independent, where a franchised property is a branded property run by a third party that pays franchise fees or royalties for the brand, marketing and reservation services.",v:"Vietnam's official tourism site groups luxury and resort experiences around enclaves such as Phu Quoc, Nha Trang, Ha Long and Da Nang, which shows the destination types where integrated resort models compete.",b:"The contract model decides who controls operations, who earns which fee and who carries the profit risk. Resort owners must also fund and maintain the extra facilities that justify the destination promise.",s:["str","marriott","vietnamTravel","fourSeasons"],t:[["Base management fee","A management fee calculated as a percentage of a hotel's revenues and paid to the operator.","marriott"],["Incentive management fee","A management fee based on a hotel's profits, which in many cases is subject to a specified return to the owner.","marriott"],["Royalty fee","A continuing franchise fee paid to the brand, usually calculated as a percentage of sales, for the use of its name and systems.","str"],["Destination resort","A larger, usually full-service property that appeals to leisure travelers and is considered a destination in itself.","str"],["Integrated resort","A resort that brings lodging, dining, recreation, events and wellness together as one destination operation."]]},
"m1-9":{i:"Vietnam's hotel sector is shaped by a diverse destination map and a formal accommodation framework, and the cited sources describe its present structure rather than a dated timeline.",w:"Vietnam's accommodation supply spans city hotels, coastal and island resorts, heritage stays and highland retreats, regulated as categories of tourist accommodation. Official sources describe the present structure of destinations and rules rather than a year-by-year history.",y:"Growth in leisure and business travel gives local and international operators a reason to build in different regions, and national regulation gives each type a minimum standard. Destination appeal and access then decide where rooms are added.",e:"Vietnam's official tourism website presents six regions from the Northern Midlands and Mountains to the Mekong Delta, with Ha Noi, Hue, Ha Long, Da Nang, Ho Chi Minh City and Phu Quoc as top destinations, which shows how varied the settings for lodging are.",v:"Decree 168/2017, effective 1 January 2018, is the official record cited for accommodation categories; current minimum conditions must be read with Decree 142/2018 and any later applicable instruments.",b:"A developer reading Vietnam's history from current sources should treat rules and destination appeal as the stable foundations and treat past growth rates as unproven until sourced. Plans need destination-specific evidence.",s:["vietnamTravel","vnDecree","vnDecree142","vnat2025"],t:[["Urban hotel","In Vietnam's decree, a tourist accommodation establishment built in an urban center to serve tourists.","vnDecree"],["Roadside hotel","In Vietnam's decree, accommodation close to roads with a parking area, serving travelers by motorbike or car or resting on long journeys.","vnDecree"],["Floating hotel","In Vietnam's decree, tourist accommodation afloat on the water that can be moved when necessary.","vnDecree"],["Tourist rest house","In Vietnam's decree, an accommodation establishment with the equipment and utilities tourists need.","vnDecree"],["Tourist camping site","In Vietnam's decree, a planned site in an area of beautiful scenery with the infrastructure and services campers need.","vnDecree"]]},
"m1-10":{i:"The global industry is a layered system in which asset owners, operators, brands and distributors each hold a different part of the economics.",w:"Global accommodation combines international groups, regional operators, independent hotels and alternative accommodation. STR's operation types are chain managed, franchised and independent, and its company types add owners, developers and membership companies.",y:"Capital, brand and operating skill rarely sit in one business, so specialists have formed around each layer and the industry has become a network of contracts. Distribution platforms have added a further layer between guests and properties.",e:"Marriott separates the hotels it manages from those it franchises or licenses and says it owns or leases very few properties, while Accor lists more than 45 brands and Four Seasons presents a service-led luxury offer, three differently structured companies in one industry.",v:"A global brand name on a Vietnamese property says which system it belongs to, but it does not show who owns the building or who earns the profit, so each role must be checked in the contract.",b:"Reading the structure correctly tells a developer which partner to approach for capital, operations or brand and what each will want in return. Mixing up the layers leads to the wrong comparisons.",s:["str","marriott","accor","fourSeasons"],t:[["Operation type","The way a hotel is run, either chain managed, franchised or independent, which determines who operates it and who pays for the brand.","str"],["Membership company","A company whose independent hotels share one membership affiliation, reservations system, marketing and quality standards with fewer constraints than a franchise.","str"],["Asset management company","A company that manages investments in hotels on behalf of an owner.","str"],["Real estate investment trust","A corporation or trust that pools investors' capital to buy and manage income property and usually distributes most earnings as dividends.","str"],["Franchised hotel","A branded property operated by a third party that pays fees or royalties to the chain for its name, marketing and reservations.","str"]]},
"m1-11":{i:"Markets can be segmented by geography, chain scale, property type, location and customer type, and a comparison is only fair within the same segment.",w:"Segmentation divides hotels by where they are, what they offer and who they serve. STR uses market and submarket for geography, chain scale and class for price tier, location types such as urban, airport and resort, and demand types of transient, group and contract.",y:"A national average hides large differences between a city business hotel and an island resort, so analysts split the market until properties are genuinely comparable. Buyers and investors also need segment-specific data to judge opportunities.",e:"In STR's classification an urban hotel is in a densely populated location in a large metropolitan area, an airport hotel mainly serves airport traffic and a resort hotel is in a market where much of the business comes from leisure or destination travel.",v:"Vietnam's official tourism site already groups travelers by experience, for example luxury and resorts, city and shopping, family, wellness and golf, and names different top destinations for each, which suggests natural segments for Vietnamese hotels.",b:"Segmentation decides which competitors, rates and benchmarks are relevant to a property. Without it, an owner may chase an average that no real guest pays or compete against hotels that do not share its customers.",s:["str","vietnamTravel"],t:[["Class","A price tier assigned to a hotel, equal to its chain scale if affiliated or based on its average rate relative to nearby chain hotels if independent.","str"],["Submarket","A geographic area that is a subset of a market, such as one district of a larger city or island market.","str"],["Transient rooms","Rooms sold to individuals or to groups occupying fewer than ten rooms per night.","str"],["Group rooms","Rooms typically sold ten or more per night under a signed agreement.","str"],["Contract rooms","A consistent block of rooms committed at an agreed rate for an extended period, with payment guaranteed whether or not they are used.","str"]]},
"m1-12":{i:"Tourism creates demand for rooms, but hotels respond with supply that arrives slowly, so occupancy and rate depend on how closely the two move together.",w:"Demand is rooms sold in a period, supply is rooms available, and the balance between them sets occupancy. Visitor trips feed demand, while construction and renovation change the rooms available.",y:"A hotel cannot be built or removed quickly, so supply lags demand and the market swings between tight and oversupplied conditions. Seasonal visits and events move demand within a year while the room count stays fixed.",e:"STR defines demand as the number of rooms sold in a period excluding complimentary rooms and supply as rooms available, so both sides of the market are counted in the same unit of room nights.",v:"Vietnam's official 2025 results record nearly 21.2 million international arrivals and 137 million domestic tourist trips, but these count visitor trips, not room nights or occupancy, so supply and demand must still be compared destination by destination.",b:"When demand outgrows supply, rate rises first and new rooms follow, and when supply outgrows demand, discounting follows. Owners need destination-level data on both sides before committing capital.",s:["str","vnat2025"],t:[["Demand","The number of rooms sold in a specified period, excluding complimentary rooms, which sets the demand side of the market balance.","str"],["Supply","The number of rooms in a hotel or set of hotels multiplied by the days in the period, also called rooms available.","str"],["Pipeline","Data on existing hotel supply and projected growth gathered from chains, management companies, tourism bureaus and developers.","str"],["Room additions","Rooms added to inventory through expansion, repurposing or reopening after renovation.","str"],["Rooms removed","Rooms taken out of inventory because they were repurposed, closed for full renovation or no longer in the rental pool.","str"]]},
"m1-13":{i:"International participants fall into distinct types, such as global multi-brand groups, luxury specialists, regional operators, owners and distributors, and each earns money differently.",w:"Participant types include multi-brand groups, service-led luxury specialists, regional operators, independent owners and online or traditional distributors. STR lists parent companies including Accor and Marriott International and company types such as owners, operators and franchise companies.",y:"Different participants specialize in capital, operation, brand or distribution, and scale advantages push the largest groups toward asset-light fee models. Smaller players differentiate through service, locality or ownership.",e:"Accor describes a portfolio of more than 45 brands across luxury, lifestyle, premium, midscale and economy, Marriott describes Classic and Distinctive brands grouped into four quality tiers, and Four Seasons focuses on luxury service.",v:"The cited sources name Vietnam's destinations but do not list its hotel operators, so a Vietnamese owner must identify each participant type, whether local operator, international brand or independent, directly from contracts and property records.",b:"Knowing the participant type tells an analyst how a company earns money and which risks it carries, so a global group's fee revenue is not comparable with one hotel's room revenue. Partner choices should follow the type of help needed.",s:["str","marriott","accor","fourSeasons"],t:[["Asset-light model","A business model in which a hotel group franchises, manages or licenses hotels rather than owning them.","marriott"],["Licensor","A company that licenses its brand names and trademarks to third parties in return for royalty and other fees.","marriott"],["Franchisor","A company that allows hotel owners to use its brand names and systems under franchise arrangements, receiving fees in return.","marriott"],["Distinctive brand","In Marriott's grouping, a brand offering memorable experiences with a unique perspective, as opposed to a Classic brand.","marriott"],["Classic brand","In Marriott's grouping, a brand offering time-honored hospitality for the modern traveler, as opposed to a Distinctive brand.","marriott"]]},
"m1-14":{i:"Occupancy, ADR and RevPAR each answer a different question about a hotel market, and none of them shows profit.",w:"Markets are measured by comparing rooms sold, rooms available and room revenue over a stated period. Occupancy is rooms sold divided by rooms available, ADR is room revenue divided by rooms sold and RevPAR is room revenue divided by rooms available.",y:"Owners, lenders and brands need shared definitions to compare properties across places and time, so industry groups publish standard metrics. Comparable measures only work when the room basis, period and currency match.",e:"STR's glossary adds index measures that compare a hotel with its competitive set, where an index of 100 means a fair share and a figure above 100 means the hotel captured more than its expected share of occupancy, rate or RevPAR.",v:"Official Vietnamese tourism results report arrivals and trips, while hotel metrics need rooms sold and room revenue, so a Vietnamese hotel should benchmark itself against a comparable competitive set rather than against national visitor growth.",b:"Reliable measurement lets an owner see whether a change in revenue came from rate, occupancy or both. Quoting one metric alone invites wrong decisions.",s:["str","vnat2025"],t:[["Occupancy index","A hotel's occupancy divided by that of its comparison group, times one hundred, also called the market penetration index.","str"],["Average rate index","A hotel's ADR divided by the ADR of its comparison group, times one hundred.","str"],["RevPAR index","A hotel's RevPAR divided by the RevPAR of its comparison group, times one hundred, also called the revenue generating index.","str"],["Competitive set","The group of hotels a property competes against, typically in the same area with similar services and amenities.","str"],["Fair share","An even distribution of supply, demand and revenue among all properties in a group, shown by an index of one hundred.","str"]]},
"m1-15":{i:"Vietnam's hotel and resort ecosystem is a set of regional markets, each with its own guests, access and season, rather than one national market.",w:"The ecosystem links owners, operators, brands, online and traditional distributors, suppliers and authorities across cities, coasts, islands, heritage towns and highlands. Vietnam's official tourism website divides the country into six regions.",y:"Geography, climate and access differ from the north to the south, so demand arrives at different times and in different forms in each region. Domestic and international guests then choose among them.",e:"The official site lists Ha Noi, Hue, Ha Long, Da Nang, Ho Chi Minh City and Phu Quoc as top destinations, and it describes the South Central Coast and Central Highlands as a mix of ancient Hoi An, sunlit beaches, island escapes and cool highland plateaus.",v:"The official site places Da Nang, Nha Trang and Da Lat in the South Central Coast and Central Highlands region, so one regional market can contain beach, city and highland hotels with very different guests.",b:"Operators enter this ecosystem region by region, matching the property to local demand and access. A plan built on a national average will misjudge every individual market.",s:["vietnamTravel","vnat2025","str"],t:[["Heritage stay","Accommodation in or near historic or cultural sites, where the setting and local character are part of what the guest buys."],["Highland retreat","A property in cool upland scenery that sells quiet, nature and a change of climate rather than city access."],["Island resort","A resort on an island whose guests depend on sea or air access and whose supplies and staff must also be brought in."],["Coastal resort","A resort on or near a beach whose demand follows weather, school holidays and the destination's flight and road links."],["Convention hotel","A property with a large room count and extensive meeting facilities, built to host conventions and large events.","str"]]},
"m1-16":{i:"Urban hotels live on weekday business and city trips, while destination hotels depend on leisure demand, seasons and access to a specific place.",w:"An urban hotel is built in a city to serve business, event and city-break guests across most of the week. A destination or resort hotel is itself part of the reason for travel and relies on seasonal leisure stays and its own facilities.",y:"City demand is spread across many sources and dates, while resort demand clusters around holidays, weather and flight access, so cost bases, staffing and pricing follow different rhythms. Destination hotels also build amenities to keep guests on property.",e:"STR defines a destination resort as a property that appeals to leisure travelers, typically sits in a resort market, is considered a destination in itself and is usually larger and full-service, in contrast to an urban location in a densely populated metropolitan area.",v:"Vietnam's official site lists Ha Noi and Ho Chi Minh City among its city and shopping enclaves and Phu Quoc, Nha Trang, Ha Long and Da Nang among its luxury and resort enclaves, and Decree 168/2017/ND-CP defines urban hotels and resorts as separate legal types.",b:"Choosing between the two models changes the capital needed, the facilities built and the way revenue is spread through the year. Resort owners carry heavier fixed costs in low season.",s:["str","vietnamTravel","vnDecree"],t:[["Urban location","A densely populated location in a large metropolitan area, where a hotel draws on city business and leisure demand.","str"],["Resort location","A location in a resort area or market where a significant source of business is leisure or destination travel.","str"],["Airport location","A location near an airport, where a hotel primarily serves demand from airport traffic.","str"],["Seasonal closure","A period of at least one calendar month, around the same time each year, when a property is closed.","str"],["Amenities","Features and services a hotel offers beyond the room, such as a restaurant, golf, pool, spa or casino.","str"]]},
"m1-17":{i:"Domestic and international guests differ in volume, timing, length of stay and booking habits, so a hotel's source-market mix shapes its calendar and channels.",w:"Domestic guests travel within their own country and international guests arrive from abroad, and the two groups differ in trip purpose, timing and how they find and book a hotel. A hotel's mix of the two shapes its seasons and its sales effort.",y:"Income, holidays, flight links and visa conditions shape each group's travel differently, so each source market rises and falls on its own drivers. A hotel serving both has more resilience but needs a wider range of sales channels.",e:"Vietnam's 2025 results show nearly 21.2 million international arrivals and 137 million domestic tourist trips, and the cited notes stress that trips can include non-hotel stays and repeat travelers, so neither figure is a count of hotel guests.",v:"Official results give national totals only, so a coastal resort in Nha Trang cannot read its own guest mix from them and has to analyse its reservations by origin, purpose and length of stay.",b:"Source-market mix affects average length of stay, channel cost, language needs and exposure to shocks in one market. Hotels that track guest origin can adjust sales and service sooner.",s:["vnat2025","vietnamTravel","str"],t:[["Source market","The country or region a guest travels from, used to group demand and plan sales and service.","str"],["Length of stay","The number of nights a guest stays in a hotel, which affects revenue management and staffing decisions.","str"],["International arrival","A visitor trip entering a country from abroad, counted as a trip rather than as room nights, unique guests, occupancy or hotel revenue.","vnat2025"],["Domestic tourist trip","A trip by a resident within the country, which may include non-hotel stays and repeat travelers and so is not a count of hotel guests.","vnat2025"],["Repeat traveler","A guest who returns to the same destination, hotel or brand, whose return is measured separately from satisfaction scores."]]},
"m1-18":{i:"Local operators and international brands play different roles in Vietnam's hotel market, and brand presence alone does not show who owns, runs or profits from a property.",w:"Local operators bring knowledge of land, labor, regulation and domestic guests, while international brands bring standards, reservation systems and loyalty reach. Many hotels combine both through franchise or management agreements.",y:"Owners want guest reach and credibility beyond their own marketing, and brands want growth in destinations where they do not wish to own property. Contracts let each side contribute what it does best.",e:"Marriott says hotel owners may choose a franchise, management or other licensing affiliation and that it competes for owners by offering its loyalty program, central reservation systems and marketing, which shows what an international brand offers a local owner.",v:"Whichever flag a hotel flies, the amended hotel-specific minimum applies to the property: Article 22 retains reception and round-the-clock staffing, while Decree 142/2018 repealed the original tourism-training clause. Brand standards and any other applicable workforce rules are separate obligations.",b:"The mix of local and international partners determines fees, control and the speed of opening. Owners should compare the full cost of a brand with the extra demand it delivers.",s:["vnDecree","vnDecree142","vnat2025","marriott","accor"],t:[["Franchisee","An owner or operator that pays a brand for the right to use its name, systems and standards while running the hotel itself.","marriott"],["Local operator","A company based in the destination that runs hotels using its own knowledge of land, labor, regulation and guests."],["International brand","A hotel name marketed across many countries with consistent standards, a booking platform and a loyalty program.","accor"],["Owner return","The profit an owner receives, which in many management agreements must reach a specified level before the operator earns an incentive fee.","marriott"],["Centralized services","Programs a brand provides to its hotels, such as loyalty, reservations and marketing, for which owners reimburse the brand.","marriott"]]},
"m1-19":{i:"Vietnamese hotels face linked challenges in supply timing, channel cost, seasonality, staffing and legal compliance, and each needs destination-level evidence.",w:"Supply challenges include new rooms arriving faster than demand, distribution challenges include commission and channel dependence, and operating challenges include staffing, seasonality and compliance with accommodation rules.",y:"Tourism growth attracts new projects in popular places, online platforms control much of the discovery of rooms, and hotels must keep staff and equipment ready all year. These pressures reinforce each other in low season.",e:"Marriott's filing warns that some rooms are booked through internet travel intermediaries that use aggressive online marketing and also offer corporate travel and group meetings, an example of the channel dependence that large and small hotels both face.",v:"As amended by Decree 142/2018, Article 22 retains at least ten bedrooms, a reception desk, shared toilets and staff on duty 24 hours a day for hotels. The original tourism-training clause was repealed; separate security, fire-safety, environmental, food-safety and other applicable rules still require their own checks.",b:"Together these challenges raise the break-even point and make low season dangerous for thinly capitalized hotels. Planning should test each challenge separately before combining them in a forecast.",s:["vnDecree","vnDecree142","vnTourismLaw","vnat2025","marriott"],t:[["Oversupply","A market condition in which rooms available grow faster than demand, pushing occupancy and rate down."],["Channel dependence","Reliance on one or a few sales channels for bookings, which weakens a hotel's bargaining position on commission and terms.","marriott"],["Commission","A fee paid to an intermediary, usually as a percentage of the booking value, for producing a reservation."],["Break-even point","The level of sales at which revenue just covers fixed and variable costs, below which the hotel loses money."],["Round-the-clock staffing","Keeping employees on duty twenty-four hours a day, which the amended Article 22 of Vietnam's accommodation decree retains as a hotel condition.","vnDecree"]]},
"m1-20":{i:"Leisure and business travel create hotel demand in different ways, with leisure following holidays and attractions and business following work activity and accessibility.",w:"Leisure demand comes from holidays, attractions, family occasions and wellness trips, while business demand comes from meetings, corporate activity and events. STR notes that MICE bookings are usually made well in advance of an event.",y:"Rising incomes and wider choice encourage leisure trips, and economic activity and events bring business travelers, so each type responds to its own drivers. Hotels respond by designing rooms and services for the guest's main purpose.",e:"Vietnam's official tourism site presents nature, culture, food, beaches, wellness, adventure, family and city experiences as separate reasons to visit, showing how many different leisure motivations a destination can offer.",v:"The same site lists golf and leisure among its experiences with Da Nang, Hoi An, Ha Long and Ho Chi Minh City as top enclaves, so a property in those places may serve both leisure and business guests.",b:"A hotel serving mainly one purpose can tune its product and pricing tightly, while a mixed property needs flexibility across weekdays and weekends. Knowing the dominant purpose guides facilities and staffing.",s:["str","vietnamTravel","fourSeasons"],t:[["MICE","Meetings, incentives, conferences and exhibitions, a tourism segment that is a significant part of business travel and hotel demand on business days.","str"],["SMERF","Social, military, educational, religious and fraternal groups, a group-booking segment valuable for midweek and off-season business.","str"],["Bleisure","A trip that combines business and leisure, such as a guest who extends a work visit to add personal days."],["Corporate account","A negotiated arrangement between a company and a hotel that sets rates, availability and billing for employee travel."],["Leisure demand","Demand for rooms from travelers on holiday or recreation trips, which follows school terms, public holidays, weather and attractions."]]},
"m1-21":{i:"Seasonality moves demand through the year and connectivity decides who can reach a destination, so both shape occupancy and rate at the property level.",w:"Seasonality is the recurring pattern of high and low demand linked to weather, holidays and events. Connectivity is how easily travelers can reach a place by air, road or rail, which sets the ceiling on how many can arrive.",y:"Climate and holiday calendars repeat each year, and a destination that is hard to reach loses guests to places that are easier to access. Hotels have costs all year, so a quiet season weighs heavily.",e:"STR gives a ski lodge closed in summer and a beach resort closed in winter as examples of seasonal closure, which it defines as a period of at least one calendar month around the same time each year.",v:"Vietnam's official tourism site describes beaches and islands, cool highland plateaus and northern mountain loops, settings that are likely to have different seasons and different access needs, so each property should read its own calendar.",b:"Seasonal swings and access limits determine when a hotel earns its money and when it must conserve cash. Pricing, staffing and maintenance plans should follow the calendar rather than an annual average.",s:["str","vietnamTravel"],t:[["Seasonality","Recurring variation in demand linked to dates, climate, holidays, events or travel patterns."],["Peak season","The part of the year when demand is strongest, allowing higher rates and fuller occupancy."],["Low season","The part of the year when demand is weakest, when fixed costs weigh heaviest on results."],["Air connectivity","The range and frequency of flights that bring travelers to a destination, setting how many can arrive."],["Holiday closure","A voluntary closure of less than one month, typically around a holiday.","str"]]},
"m1-22":{i:"Economic cycles move demand and rate while labor and operating costs set how much of each room dollar remains, so profit can fall even when revenue holds.",w:"In a downturn, travel budgets shrink and rates soften, while wages, energy and supplies keep rising. Labor is a major part of hotel cost and cannot be adjusted instantly, so staffing decisions strongly affect margin.",y:"Hotels carry high fixed costs, so a fall in revenue reaches profit quickly. Wage pressure and skills shortages push costs up independently of demand.",e:"STR's glossary defines flow through as the share of an incremental revenue change that reaches gross operating profit, and flex as the profit saved when revenue falls, two measures that show how cost structure turns revenue swings into profit swings.",v:"The amended Article 22 retains employees on duty 24 hours a day, which creates a minimum staffing commitment regardless of occupancy. Decree 142/2018 repealed the original tourism-training clause, and the cited sources provide no Vietnamese wage benchmark.",b:"Owners should test how a fall in occupancy or a rise in wages flows through to profit, using the property's own cost structure. Contracts that share risk with operators matter more in weak years.",s:["str","vnDecree","vnDecree142"],t:[["Flow through","The percentage of incremental profit that reaches the bottom line from each additional dollar of revenue.","str"],["Flex","The amount of profit saved, as a share of a revenue fall, when a hotel cuts cost as revenue declines.","str"],["Fixed cost","A cost that stays broadly the same whether or not rooms sell, such as the building, core staff and insurance."],["Variable cost","A cost that rises and falls with the number of rooms sold, such as laundry, amenities and some utilities."],["Full-time equivalent employee","A staffing measure that converts all hours worked, including part-time hours, into the number of full-time employees.","str"]]},
"m1-23":{i:"Technology and online distribution have changed how rooms are found, priced, sold and operated, and the gains depend on integration and on who controls the guest relationship.",w:"Hotels now rely on connected systems for reservations, pricing, guest records and building controls, while travelers search and book through websites, apps, global distribution systems and online travel platforms. Each channel has a cost and a data trade-off.",y:"Guests compare options online and expect fast, personal service, and brands compete through direct channels and loyalty programs. Better data also helps hotels forecast demand and manage energy.",e:"Marriott's filing lists reservation, customer relationship management, analytics, revenue management and property management systems among the technology it uses and describes its direct digital channels and loyalty program as central to its strategy.",v:"The cited sources record Vietnam's official tourism website and visitor statistics but no data on hotel technology adoption in Vietnam, so a Vietnamese hotel must baseline its own systems before assuming benefits.",b:"Technology raises revenue or lowers cost only when systems share data and staff use them consistently. Owners should compare channel cost with the value of the guest relationship.",s:["marriott","str","doeControls"],t:[["Global distribution system","A computerized network giving travel agents and other professionals information and booking services across hotels, flights and other travel products.","str"],["Property management system","Software that coordinates reservations, room inventory, check-in, guest records and billing in a hotel."],["Customer relationship management","Systems that hold guest records and preferences so a hotel can communicate with and serve guests over time.","marriott"],["Direct channel","A booking route controlled by the hotel or brand, such as its website, mobile app or call center.","marriott"],["Energy management control system","A building control system that manages heating, cooling, lighting and other equipment to maintain comfort and limit energy use.","doeControls"]]},
"m1-24":{i:"Regulation sets the minimum a hotel must provide and sustainability sets a measured target for resource use, and both shape design, operations and cost.",w:"Regulation covers the categories and minimum conditions that apply to a property, along with other rules for safety, labor and food. Sustainability programs set measurable goals for energy, water and materials.",y:"Governments require basic standards for guests and workers, while owners, lenders and travelers increasingly expect hotels to manage resources and climate risk. IFC notes that extreme weather raises operating cost and can reduce tourist numbers.",e:"IFC says EDGE certification requires solutions that reduce energy, water and the energy used to make building materials by at least 20 percent, and the cited note stresses that this is measured against a local baseline and is not a guaranteed saving.",v:"The current framework has two layers: Article 49 of the Tourism Law requires tourist-accommodation businesses to satisfy registration and applicable security, fire-safety, environmental and food-safety rules; amended Article 22 retains hotel-specific conditions such as reception, shared toilets, specified room equipment and 24-hour staffing. Decree 142/2018 repealed the original Article 22 utilities and tourism-training clauses.",b:"Compliance protects the license to operate, while resource efficiency can lower cost and meet guest and lender expectations. Claims about savings should rest on baselines and measurement at the property.",s:["ifcHotels","doeControls","vnTourismLaw","vnDecree","vnDecree142"],t:[["EDGE certification","A green-building certification from IFC that requires solutions cutting energy, water and embodied energy in materials by at least a set threshold.","ifcHotels"],["Local baseline","The typical resource use of comparable buildings in the same place, against which an improvement is measured.","ifcHotels"],["Embodied energy","The energy used to make the building materials that go into a hotel, as distinct from the energy used to operate it.","ifcHotels"],["Minimum conditions","The basic facilities and services a type of accommodation must have under Vietnam's accommodation decree as amended, separate from the general business conditions in the Tourism Law.","vnDecree"],["Building controls","The intelligent systems that manage a building's heating, cooling, hot water, lighting and other equipment as one integrated whole.","doeControls"]]}
};
